function css(){if(document.getElementById('fpon-0903-css'))return;const s=document.createElement('style');s.id='fpon-0903-css';s.textContent='.news4{grid-template-columns:repeat(2,1fr)!important;gap:12px!important}.news4 .news{min-height:168px!important;position:relative;padding:15px 108px 38px 16px!important;overflow:hidden;cursor:pointer}.news-thumb{position:absolute;right:0;top:0;width:96px;height:100%;display:flex;align-items:center;justify-content:center;font-size:44px;background:linear-gradient(145deg,#eef5fc,#dfeaf6);border-left:1px solid #e3eaf1}.news-kicker{display:inline-flex!important;padding:5px 10px!important;border-radius:999px!important;background:#eaf3ff!important;color:#195e9f!important;font-size:12px!important;font-weight:900!important;margin-bottom:8px!important}.variable-live{padding:18px;border:1px solid #dce6f0;border-radius:16px;background:#f8fbff}.warn{margin-top:10px;font-size:12px;line-height:1.6;color:#677789}.econ-values{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-top:4px}.econ-values div{font-size:9px;text-align:center;background:#f5f8fb;padding:4px 1px;border-radius:5px}.metric-week{margin-top:8px;border-top:1px solid #e7edf3;padding-top:8px}@media(max-width:800px){.news4{grid-template-columns:1fr!important}}';document.head.appendChild(s)}
function quote(){const hero=document.querySelector('.hero');if(!hero||document.getElementById('fpon-q0903'))return;const q=document.createElement('div');q.id='fpon-q0903';q.style.cssText='margin:10px 0;padding:12px 16px;border-radius:14px;background:linear-gradient(135deg,#f6f9ff,#fffaf3);border:1px solid #e4e9f1';q.innerHTML='<div style="font-size:11px;font-weight:900;color:#7a5a18">오늘의 명언</div><div style="font-size:17px;font-weight:800;color:#243c5a;margin-top:5px">“꾸준함은 재능을 이기는 가장 조용한 힘입니다.”</div>';hero.appendChild(q)}
function news(){const sec=[...document.querySelectorAll('section')].find(x=>x.querySelector('h2')&&x.querySelector('h2').textContent.includes('오늘의 뉴스'));if(!sec)return;let g=sec.querySelector('.news4');if(!g){g=document.createElement('div');g.className='news4';sec.appendChild(g)}g.innerHTML=NEWS.map(x=>'<div class="news"><span class="news-kicker">'+x[0]+'</span><b>'+x[1]+'</b><span>'+x[2]+'</span><div class="news-thumb">'+x[3]+'</div></div>').join('')}
function econ(){[['.ec.stocks','코스피','kospi'],['.ec.stocks','코스닥','kosdaq']].forEach(([sel,name,key])=>{const c=document.querySelector(sel);if(!c)return;[...c.querySelectorAll('.m')].forEach(m=>{if(!(m.querySelector('.mn')?.textContent||'').includes(name))return;m.querySelectorAll('.metric-week').forEach(x=>x.remove());const o=ECON[key],d=document.createElement('div');d.className='metric-week';d.innerHTML='<div style="font-size:10px;font-weight:900;color:#64778d">최근 거래일 비교 · 9/2 마감</div><div class="econ-values">'+o.labels.map((l,i)=>'<div><b>'+l+'</b><br>'+o.values[i].toLocaleString('ko-KR',{maximumFractionDigits:2})+'</div>').join('')+'</div>';m.appendChild(d);const mv=m.querySelector('.mv');if(mv)mv.textContent=o.values.at(-1).toLocaleString('ko-KR',{maximumFractionDigits:2})})})}
